        private ArrayList GetInsertScreenStatement(int aiUserId, int aiInsertById, TreeNode[] aoTreeNodes)
        {
            var oArrInsert = new ArrayList();

            for (int iCount = 0; iCount < aoTreeNodes.Length; iCount++)
            {
                string sInsertUserScreenId = "INSERT INTO [UserScreenPermissions](" +
                                             " Screen_Id" +
                                             ",User_Id" +
                                             ",Inserted_By_Id" +
                                             ") VALUES (" +
                                             " " + Convert.ToInt32(aoTreeNodes[iCount].Value) + //(aoTreeNodes.GetValue(iCount)) +
                                             " ," + aiUserId +
                                             " ," + aiInsertById +
                                             ")";

                oArrInsert.Add(sInsertUserScreenId);
            }

            return oArrInsert;
        }

